"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[492],{3036:n=>{n.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new Signal object\\n\\n```lua\\nlocal Signal = NewSignal.new()\\n```","params":[],"returns":[{"desc":"","lua_type":"Signal"}],"function_type":"static","source":{"line":410,"path":"src/NewSignal.luau"}},{"name":"Connect","desc":"Connects a function to the signal, which will be called everytime the signal is fired.\\n\\n```lua\\nSignal:Connect(function(Message, Number)\\n\\tprint(Message, Number)\\nend)\\n\\nSignal:Fire(\\"Hello\\", 25)\\n```","params":[{"name":"Callback","desc":"","lua_type":"(...) -> ()"}],"returns":[{"desc":"","lua_type":"Connection"}],"function_type":"method","source":{"line":427,"path":"src/NewSignal.luau"}},{"name":"Once","desc":"Connects a function to the signal, which will be called once and disconnected immediatly.\\n\\n```lua\\nSignal:Once(function(Message, Number)\\n\\tprint(Message, Number)\\nend)\\n\\nSignal:Fire(\\"Hello\\", 25)\\nSignal:Fire(\\"This message will not get printed\\", 10)\\n```","params":[{"name":"Callback","desc":"","lua_type":"(...) -> ()"}],"returns":[{"desc":"","lua_type":"Connection"}],"function_type":"method","source":{"line":445,"path":"src/NewSignal.luau"}},{"name":"Wait","desc":"Yields the current thread until `:Fire` occurs, and returns the arguments fired from the signal.\\n\\n```lua\\ntask.spawn(function()\\n\\tprint(Signal:Wait()) --\x3e \\"Test\\", 89, nil, false\\nend)\\nSignal:Fire(\\"Test\\", 89, nil, false)\\n```","params":[],"returns":[{"desc":"","lua_type":"... any"}],"function_type":"method","yields":true,"source":{"line":467,"path":"src/NewSignal.luau"}},{"name":"FireAsync","desc":"Fires a Signal object Asynchronously with the arguments passed.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireAsync(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":513,"path":"src/NewSignal.luau"}},{"name":"FireSafe","desc":"Fires a Signal object with the arguments passed using a `pcall`.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireSafe(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":542,"path":"src/NewSignal.luau"}},{"name":"DisconnectAll","desc":"Disconnects all current Connections from the Signal.\\n\\n```lua\\nSignal:Connect(function(Args) end)\\n\\nSignal:DisconnectAll(true) -- All connections are disconnected immediately (It will not be Queued and will break the current iteration)\\n```","params":[{"name":"Immediate","desc":"","lua_type":"boolean?"}],"returns":[],"function_type":"method","source":{"line":569,"path":"src/NewSignal.luau"}},{"name":"Destroy","desc":"Destroys a Signal object, disconnecting all connections and making it unusable.\\n\\n```lua\\nSignal:Connect(function(Args) end)\\n\\nSignal:Destroy() -- Destroys the signal and disconnects all connections\\n```","params":[],"returns":[],"function_type":"method","source":{"line":615,"path":"src/NewSignal.luau"}},{"name":"Fire","desc":"Alias for FireAsync by default.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:Fire(\\"Something...\\") -- Same behaviour as `FireAsync`\\n```","params":[],"returns":[],"function_type":"method","source":{"line":646,"path":"src/NewSignal.luau"}}],"properties":[],"types":[],"name":"Signal","desc":"A Signal is a class that is used to substitute the use of Bindable Events, this implementation\\ntries to handle most of the edge cases that could happen, while being as performant as possible,\\nwith additional features for Advanced users such as selectable disconnect mode.\\n\\nThis implementation tries to have similar API to the standard signal module, [GoodSignal](https://devforum.roblox.com/t/lua-signal-class-comparison-optimal-goodsignal-class/1387063),\\nwith some additional features.\\n\\nQuick example:\\n```lua\\nlocal NewSignal = require(path.to.NewSignal)\\n\\n-- Create a signal\\nlocal Signal = NewSignal.new()\\n\\n-- Connect a listener\\nlocal Connection = Signal:Connect(function(Param)\\n    print(`The Signal Got fired, param: {Param}`)\\nend)\\n\\n-- Fire the signal\\nSignal:Fire(\\"Hello\\")\\n\\n-- Disconnect the listener\\nConnection:Disconnect()\\n```","source":{"line":99,"path":"src/NewSignal.luau"}}')}}]);